//! The frozen, built-in workspace `cargolike` reports on.

pub struct Package {
    pub name: &'static str,
    pub version: &'static str,
    pub deps: &'static [&'static str],
}

/// Already in name order; every listing walks this slice as-is.
pub const PACKAGES: &[Package] = &[
    Package { name: "cli", version: "1.0.0", deps: &["core", "util"] },
    Package { name: "core", version: "0.3.1", deps: &[] },
    Package { name: "util", version: "0.2.0", deps: &["core"] },
];

pub fn find(name: &str) -> Option<&'static Package> {
    PACKAGES.iter().find(|p| p.name == name)
