//! The layered configuration: known keys, the layers that carry values, and
//! the per-type merge that turns them into one effective value plus a
//! provenance.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

// ---------------------------------------------------------------------------
// Keys
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Kind {
    Int,
    Bool,
    Str,
    List,
    Enum(&'static [&'static str]),
}

pub const KEYS: &[(&str, Kind)] = &[
    ("build.jobs", Kind::Int),
    ("build.features", Kind::List),
    ("build.target", Kind::Str),
    ("net.offline", Kind::Bool),
    ("term.color", Kind::Enum(&["auto", "always", "never"])),
    ("term.output", Kind::Enum(&["auto", "text", "term", "json"])),
];

pub fn kind_of(key: &str) -> Option<Kind> {
    KEYS.iter().find(|(name, _)| *name == key).map(|(_, kind)| *kind)
}

/// `CARGOLIKE_` + the section + `_` + the key, uppercased.
pub fn env_name(key: &str) -> String {
    format!("CARGOLIKE_{}", key.replace('.', "_").to_uppercase())
}

fn default_value(key: &str) -> Option<Value> {
    match key {
        "build.jobs" => Some(Value::Int(1)),
        "build.features" => Some(Value::List(Vec::new())),
        "build.target" => None,
        "net.offline" => Some(Value::Bool(false)),
        "term.color" => Some(Value::Str("auto".into())),
        "term.output" => Some(Value::Str("auto".into())),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Values
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Int(i64),
    Bool(bool),
    Str(String),
    List(Vec<String>),
}

impl Value {
    /// How `config get` and `config list` spell the value.
    pub fn render(&self) -> String {
        match self {
            Value::Int(n) => n.to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Str(s) => s.clone(),
            Value::List(items) => format!("[{}]", items.join(",")),
        }
    }

    pub fn to_json(&self) -> serde_json::Value {
        match self {
            Value::Int(n) => serde_json::Value::from(*n),
            Value::Bool(b) => serde_json::Value::from(*b),
            Value::Str(s) => serde_json::Value::from(s.clone()),
            Value::List(items) => serde_json::Value::from(items.clone()),
        }
    }

    pub fn as_str(&self) -> &str {
        match self {
            Value::Str(s) => s,
            _ => "",
        }
    }
}

/// Read text against a key's type. Every layer that carries a value as text
/// — the flags, `--config`, and the environment variables — comes through here.
pub fn parse_text(key: &str, text: &str) -> Result<Value, CfgError> {
    let bad = || CfgError::InvalidValue { key: key.to_string(), text: text.to_string() };
    match kind_of(key) {
        None => Err(CfgError::UnknownKey { key: key.to_string(), usage: true }),
        Some(Kind::Int) => {
            if text.is_empty() || !text.chars().all(|c| c.is_ascii_digit()) {
                return Err(bad());
            }
            let n: i64 = text.parse().map_err(|_| bad())?;
            if n < 1 {
                return Err(bad());
            }
            Ok(Value::Int(n))
        }
        Some(Kind::Bool) => match text {
            "true" => Ok(Value::Bool(true)),
            "false" => Ok(Value::Bool(false)),
            _ => Err(bad()),
        },
        Some(Kind::Str) => Ok(Value::Str(text.to_string())),
        Some(Kind::Enum(allowed)) => {
            if allowed.contains(&text) {
                Ok(Value::Str(text.to_string()))
            } else {
                Err(bad())
            }
        }
        Some(Kind::List) => {
            if text.is_empty() {
                Ok(Value::List(Vec::new()))
            } else {
                Ok(Value::List(text.split(',').map(|s| s.to_string()).collect()))
            }
        }
    }
}

/// Read a TOML value against a key's type. A wrong-typed file value is the
/// same configuration error a wrong-typed text value is.
fn parse_toml(key: &str, value: &toml::Value) -> Result<Value, CfgError> {
    let bad = || CfgError::InvalidValue { key: key.to_string(), text: toml_text(value) };
    match kind_of(key) {
        None => Err(CfgError::UnknownKey { key: key.to_string(), usage: false }),
        Some(Kind::Int) => match value.as_integer() {
            Some(n) if n >= 1 => Ok(Value::Int(n)),
            _ => Err(bad()),
        },
        Some(Kind::Bool) => value.as_bool().map(Value::Bool).ok_or_else(bad),
        Some(Kind::Str) => value.as_str().map(|s| Value::Str(s.to_string())).ok_or_else(bad),
        Some(Kind::Enum(allowed)) => match value.as_str() {
            Some(s) if allowed.contains(&s) => Ok(Value::Str(s.to_string())),
            _ => Err(bad()),
        },
        Some(Kind::List) => match value.as_array() {
            Some(items) => {
                let mut out = Vec::with_capacity(items.len());
                for item in items {
                    match item.as_str() {
                        Some(s) => out.push(s.to_string()),
                        None => return Err(bad()),
                    }
                }
                Ok(Value::List(out))
            }
            None => Err(bad()),
        },
    }
}

/// How an offending file value is named back to the user: the same spelling
/// the text layers use, so `jobs = "many"` reports `many`.
fn toml_text(value: &toml::Value) -> String {
    match value {
        toml::Value::String(s) => s.clone(),
        toml::Value::Integer(n) => n.to_string(),
        toml::Value::Float(f) => f.to_string(),
        toml::Value::Boolean(b) => b.to_string(),
        toml::Value::Datetime(d) => d.to_string(),
        toml::Value::Array(items) => {
            format!("[{}]", items.iter().map(toml_text).collect::<Vec<_>>().join(","))
        }
        toml::Value::Table(_) => "table".to_string(),
    }
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub enum CfgError {
    /// `usage` separates a key typed on the command line (exit 2) from a key
    /// found in a config file (exit 101).
    UnknownKey { key: String, usage: bool },
    MalformedOverride(String),
    InvalidValue { key: String, text: String },
    UnknownPackage(String),
    UnreadableFile(PathBuf),
}

impl CfgError {
    pub fn status(&self) -> u8 {
        match self {
            CfgError::UnknownKey { usage: true, .. } | CfgError::MalformedOverride(_) => 2,
            _ => 101,
        }
    }

    pub fn message(&self) -> String {
        match self {
            CfgError::UnknownKey { key, .. } => {
                format!("cargolike: unknown config key: {}\n", key)
            }
            CfgError::MalformedOverride(arg) => {
                format!("cargolike: malformed --config override: {}\n", arg)
            }
            CfgError::InvalidValue { key, text } => {
                format!("cargolike: invalid value for {}: {}\n", key, text)
            }
            CfgError::UnknownPackage(name) => {
                format!("cargolike: no package named {} in the workspace\n", name)
            }
            CfgError::UnreadableFile(path) => {
                format!("cargolike: malformed config file: {}\n", path.display())
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Origins
// ---------------------------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Origin {
    Flag,
    Override,
    Environment,
    Project,
    User,
    Default,
    Merged,
}

impl Origin {
    pub fn as_str(self) -> &'static str {
        match self {
            Origin::Flag => "flag",
            Origin::Override => "override",
            Origin::Environment => "environment",
            Origin::Project => "project",
            Origin::User => "user",
            Origin::Default => "default",
            Origin::Merged => "merged",
        }
    }
}

// ---------------------------------------------------------------------------
// Layers
// ---------------------------------------------------------------------------

type Layer = BTreeMap<String, Value>;

/// The per-invocation flags that name a config key.
#[derive(Clone, Debug, Default)]
pub struct Flags {
    /// Raw `--config` arguments, in command-line order.
    pub overrides: Vec<String>,
    pub jobs: Option<String>,
    pub features: Option<String>,
    /// The framework's own `--output`, when it names a `term.output` value.
    pub output: Option<String>,
}

fn read_file(path: &Path) -> Result<Option<Layer>, CfgError> {
    let text = match std::fs::read_to_string(path) {
        Ok(text) => text,
        Err(_) => return Ok(None),
    };
    let table: toml::Value =
        toml::from_str(&text).map_err(|_| CfgError::UnreadableFile(path.to_path_buf()))?;
    let table = match table.as_table() {
        Some(table) => table,
        None => return Err(CfgError::UnreadableFile(path.to_path_buf())),
    };

    // Both the table form and the dotted form arrive here as nested tables, so
    // one flattening pass reads either spelling.
    let mut layer = Layer::new();
    for (section, value) in table {
        let entries = match value.as_table() {
            Some(entries) => entries,
            None => {
                return Err(CfgError::UnknownKey { key: section.clone(), usage: false });
            }
        };
        for (name, value) in entries {
            let key = format!("{}.{}", section, name);
            if kind_of(&key).is_none() {
                return Err(CfgError::UnknownKey { key, usage: false });
            }
            layer.insert(key.clone(), parse_toml(&key, value)?);
        }
    }
    Ok(Some(layer))
}

fn user_file() -> PathBuf {
    match std::env::var_os("CARGOLIKE_CONFIG_HOME") {
        Some(home) => PathBuf::from(home).join("config.toml"),
        None => {
            let home = std::env::var_os("HOME").map(PathBuf::from).unwrap_or_default();
            home.join(".config").join("cargolike").join("config.toml")
        }
    }
}

/// Every `.cargolike/config.toml` found by walking up from the current
/// directory, nearest first. The walk does not stop at the first one.
fn project_files() -> Result<Vec<Layer>, CfgError> {
    let cwd = match std::env::current_dir() {
        Ok(cwd) => cwd,
        Err(_) => return Ok(Vec::new()),
    };
    let mut layers = Vec::new();
    let mut dir = Some(cwd.as_path());
    while let Some(current) = dir {
        let path = current.join(".cargolike").join("config.toml");
        if let Some(layer) = read_file(&path)? {
            layers.push(layer);
        }
        dir = current.parent();
    }
    Ok(layers)
}

fn env_layer() -> Result<Layer, CfgError> {
    let mut layer = Layer::new();
    for (key, _) in KEYS {
        if let Some(text) = std::env::var_os(env_name(key)) {
            let text = text.to_string_lossy().into_owned();
            layer.insert((*key).to_string(), parse_text(key, &text)?);
        }
    }
    Ok(layer)
}

fn override_layer(args: &[String]) -> Result<Layer, CfgError> {
    let mut layer = Layer::new();
    for arg in args {
        let (key, text) = match arg.split_once('=') {
            Some(split) => split,
            None => return Err(CfgError::MalformedOverride(arg.clone())),
        };
        if kind_of(key).is_none() {
            return Err(CfgError::UnknownKey { key: key.to_string(), usage: true });
        }
        // Repeating a key takes the last assignment on the command line.
        layer.insert(key.to_string(), parse_text(key, text)?);
    }
    Ok(layer)
}

// ---------------------------------------------------------------------------
// Resolution
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
pub struct Entry {
    pub value: Value,
    pub origin: Origin,
}

#[derive(Clone, Debug, Default)]
pub struct Resolved {
    entries: BTreeMap<String, Entry>,
}

impl Resolved {
    pub fn get(&self, key: &str) -> Option<&Entry> {
        self.entries.get(key)
    }

    pub fn entries(&self) -> impl Iterator<Item = (&String, &Entry)> {
        self.entries.iter()
    }

    pub fn jobs(&self) -> i64 {
        match self.get("build.jobs").map(|e| &e.value) {
            Some(Value::Int(n)) => *n,
            _ => 1,
        }
    }

    pub fn features(&self) -> Vec<String> {
        match self.get("build.features").map(|e| &e.value) {
            Some(Value::List(items)) => items.clone(),
            _ => Vec::new(),
        }
    }

    pub fn color(&self) -> &str {
        self.get("term.color").map(|e| e.value.as_str()).unwrap_or("auto")
    }

    pub fn output(&self) -> &str {
        self.get("term.output").map(|e| e.value.as_str()).unwrap_or("auto")
    }

    /// The output mode the framework is asked for: `term.output`, with `auto`
    /// answered by `term.color`.
    pub fn output_mode(&self) -> &'static str {
        match self.output() {
            "json" => "json",
            "text" => "text",
            "term" => "term",
            _ => match self.color() {
                "never" => "text",
                "always" => "term",
                _ => "auto",
            },
        }
    }
}

pub fn resolve(flags: &Flags) -> Result<Resolved, CfgError> {
    let user = read_file(&user_file())?.unwrap_or_default();
    let projects = project_files()?; // nearest first
    let env = env_layer()?;
    let overrides = override_layer(&flags.overrides)?;

    let flag_jobs = match &flags.jobs {
        Some(text) => Some(parse_text("build.jobs", text)?),
        None => None,
    };
    let flag_features = match &flags.features {
        Some(text) => Some(parse_text("build.features", text)?),
        None => None,
    };
    let flag_output = match &flags.output {
        Some(text) => Some(parse_text("term.output", text)?),
        None => None,
    };
    let no_color = std::env::var_os("NO_COLOR").is_some();

    let mut entries = BTreeMap::new();
    for (key, kind) in KEYS {
        let key = *key;
        let resolved = if matches!(kind, Kind::List) {
            resolve_list(key, &user, &projects, &env, &overrides, flag_features.as_ref())
        } else {
            let flag = match key {
                "build.jobs" => flag_jobs.clone(),
                "term.output" => flag_output.clone(),
                _ => None,
            };
            resolve_scalar(key, &user, &projects, &env, &overrides, flag, no_color)
        };
        if let Some(entry) = resolved {
            entries.insert(key.to_string(), entry);
        }
    }
    Ok(Resolved { entries })
}

fn resolve_scalar(
    key: &str,
    user: &Layer,
    projects: &[Layer],
    env: &Layer,
    overrides: &Layer,
    flag: Option<Value>,
    no_color: bool,
) -> Option<Entry> {
    if let Some(value) = flag {
        return Some(Entry { value, origin: Origin::Flag });
    }
    if let Some(value) = overrides.get(key) {
        return Some(Entry { value: value.clone(), origin: Origin::Override });
    }
    if let Some(value) = env.get(key) {
        return Some(Entry { value: value.clone(), origin: Origin::Environment });
    }
    // `NO_COLOR` sits between the file layers and the environment layer: it
    // outranks every config file and loses to `CARGOLIKE_TERM_COLOR`.
    if key == "term.color" && no_color {
        return Some(Entry { value: Value::Str("never".into()), origin: Origin::Environment });
    }
    // Among project files the one nearest the current directory is the higher
    // layer, and every project file outranks the user file.
    for layer in projects {
        if let Some(value) = layer.get(key) {
            return Some(Entry { value: value.clone(), origin: Origin::Project });
        }
    }
    if let Some(value) = user.get(key) {
        return Some(Entry { value: value.clone(), origin: Origin::User });
    }
    default_value(key).map(|value| Entry { value, origin: Origin::Default })
}

fn resolve_list(
    key: &str,
    user: &Layer,
    projects: &[Layer],
    env: &Layer,
    overrides: &Layer,
    flag: Option<&Value>,
) -> Option<Entry> {
    let mut items: Vec<(String, Origin)> = Vec::new();
    let base_origin;

    let replacement = overrides
        .get(key)
        .map(|value| (value, Origin::Override))
        .or_else(|| env.get(key).map(|value| (value, Origin::Environment)));

    if let Some((Value::List(values), origin)) = replacement {
        // A list set from the environment or through `--config` replaces the
        // merged file list instead of appending to it.
        items.extend(values.iter().map(|item| (item.clone(), origin)));
        base_origin = origin;
    } else {
        // File layers concatenate: the user file's items ahead of every
        // project file's, then the farthest ancestor through to the nearest.
        let mut declared = None;
        if let Some(Value::List(values)) = user.get(key) {
            items.extend(values.iter().map(|item| (item.clone(), Origin::User)));
            declared = Some(Origin::User);
        }
        for layer in projects.iter().rev() {
            if let Some(Value::List(values)) = layer.get(key) {
                items.extend(values.iter().map(|item| (item.clone(), Origin::Project)));
                declared = Some(Origin::Project);
            }
        }
        base_origin = declared.unwrap_or(Origin::Default);
    }

    // The `--features` flag appends to whatever that resolution produced.
    if let Some(Value::List(values)) = flag {
        items.extend(values.iter().map(|item| (item.clone(), Origin::Flag)));
    }

    // Repeated items collapse to their first occurrence, preserving order.
    let mut seen = Vec::new();
    items.retain(|(item, _)| {
        if seen.iter().any(|s| s == item) {
            false
        } else {
            seen.push(item.clone());
            true
        }
    });

    let mut layers: Vec<Origin> = Vec::new();
    for (_, origin) in &items {
        if !layers.contains(origin) {
            layers.push(*origin);
        }
    }
    let origin = match layers.len() {
        0 => base_origin,
        1 => layers[0],
        _ => Origin::Merged,
    };

    Some(Entry {
        value: Value::List(items.into_iter().map(|(item, _)| item).collect()),
        origin,
    })
}

