}

#[derive(Serialize)]
pub struct BuildView {
    pub units: Vec<BuildUnit>,
}

#[derive(Serialize)]
pub struct BuildUnit {
    pub name: String,
    pub version: String,
    pub jobs: i64,
    pub features: Vec<String>,
}

#[derive(Serialize)]
pub struct ConfigGetView {
    pub key: String,
    pub value: serde_json::Value,
    pub origin: String,
}

/// `config list` serializes as one object mapping each key to its value, so
