//! What `main` resolves once and every handler reads back.

use crate::config::{CfgError, Resolved};
use standout::cli::ExternalFailure;

pub struct AppData {
    /// Configuration resolution is a whole-invocation concern, so a failure is
    /// carried to whichever handler runs rather than short-circuiting `main`.
    pub outcome: Result<Resolved, CfgError>,
}

impl AppData {
    pub fn config(&self) -> Result<&Resolved, anyhow::Error> {
        match &self.outcome {
            Ok(resolved) => Ok(resolved),
            Err(error) => Err(fail(error)),
        }
    }
}

/// `cargolike` owns its exit codes and its diagnostic prose, so the errors
/// this app reports travel as declared external failures: the status and the
/// verbatim stderr payload are the application's, not the framework's.
pub fn fail(error: &CfgError) -> anyhow::Error {
    ExternalFailure::new(error.status(), error.message())
        .expect("cargolike statuses are nonzero")
        .into()
}

/// `config get` on a known key with no effective value: exit 1, and nothing on
/// either stream.
pub fn no_value() -> anyhow::Error {
    ExternalFailure::new(1, String::new()).expect("1 is nonzero").into()
}

