//! CLI adapters: they read the selection off the command line, ask the
//! resolved configuration and the frozen workspace for facts, and return view
//! data.

use standout::cli::{CommandContext, Output};
use standout::handler;

use crate::config::CfgError;
use crate::state::{fail, AppData};
use crate::views::*;
use crate::workspace;

fn selected(
    ctx: &CommandContext,
    package: Option<String>,
) -> Result<Vec<&'static workspace::Package>, anyhow::Error> {
    // A configuration error is a whole-invocation failure, so it is reported
    // before the selection is even looked at.
    ctx.app_state.get_required::<AppData>()?.config()?;
    workspace::select(package.as_deref())
        .map_err(|name| fail(&CfgError::UnknownPackage(name)))
}

#[handler]
pub fn metadata(
    #[arg] package: Option<String>,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<MetadataView>, anyhow::Error> {
    let packages = selected(ctx, package)?
        .into_iter()
        .map(|pkg| PackageView {
            name: pkg.name.to_string(),
            version: pkg.version.to_string(),
            dependencies: pkg.deps.iter().map(|d| d.to_string()).collect(),
        })
        .collect();
    Ok(Output::Render(MetadataView { packages }))
}

#[handler]
pub fn tree(
    #[arg] package: Option<String>,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<TreeView>, anyhow::Error> {
    // `tree` is rooted at one package, `cli` by default.
    let root = match package {
        Some(name) => selected(ctx, Some(name))?[0],
        None => {
            ctx.app_state.get_required::<AppData>()?.config()?;
            workspace::find("cli").expect("cli is in the frozen workspace")
        }
    };

    let mut lines = vec![TreeLine {
        prefix: String::new(),
        name: root.name.to_string(),
        version: root.version.to_string(),
    }];
    walk(root, "", &mut lines);
    Ok(Output::Render(TreeView { lines }))
}

/// A package reached twice is printed twice — there is no deduplication.
fn walk(pkg: &'static workspace::Package, prefix: &str, lines: &mut Vec<TreeLine>) {
    let mut deps: Vec<&str> = pkg.deps.to_vec();
    deps.sort_unstable();
    for (index, name) in deps.iter().enumerate() {
        let dep = match workspace::find(name) {
            Some(dep) => dep,
            None => continue,
        };
        let last = index + 1 == deps.len();
        lines.push(TreeLine {
            prefix: format!("{}{}", prefix, if last { "└── " } else { "├── " }),
            name: dep.name.to_string(),
            version: dep.version.to_string(),
        });
        walk(dep, &format!("{}{}", prefix, if last { "    " } else { "│   " }), lines);
    }
}

#[handler]
pub fn build(
    #[arg] package: Option<String>,
    #[ctx] ctx: &CommandContext,
) -> Result<Output<BuildView>, anyhow::Error> {
    let packages = selected(ctx, package)?;
    let config = ctx.app_state.get_required::<AppData>()?.config()?;
    let units = packages
        .into_iter()
        .map(|pkg| BuildUnit {
            name: pkg.name.to_string(),
            version: pkg.version.to_string(),
            jobs: config.jobs(),
            features: config.features(),
        })
        .collect();
    Ok(Output::Render(BuildView { units }))
}

pub mod config {
    use super::*;
    use crate::config::kind_of;
    use crate::state::no_value;

    #[handler]
    pub fn get(
        #[arg] key: String,
        #[ctx] ctx: &CommandContext,
    ) -> Result<Output<ConfigGetView>, anyhow::Error> {
        let resolved = ctx.app_state.get_required::<AppData>()?.config()?;
        if kind_of(&key).is_none() {
            return Err(fail(&CfgError::UnknownKey { key, usage: true }));
        }
        let entry = match resolved.get(&key) {
            Some(entry) => entry,
            None => return Err(no_value()),
        };
        Ok(Output::Render(ConfigGetView {
            key,
            value: entry.value.to_json(),
            origin: entry.origin.as_str().to_string(),
        }))
    }

    #[handler]
    pub fn list(#[ctx] ctx: &CommandContext) -> Result<Output<ConfigListView>, anyhow::Error> {
        let resolved = ctx.app_state.get_required::<AppData>()?.config()?;
        let mut map = ConfigListView::new();
        for (key, entry) in resolved.entries() {
            map.insert(key.clone(), entry.value.to_json());
        }
        Ok(Output::Render(map))
    }
}

