/// Pass 2 of the render pipeline reads `[...]` as a style tag, so a literal
/// bracket in a value has to be escaped on its way into the rendered text.
fn literal(text: &str) -> String {
    text.replace('[', "\\[").replace(']', "\\]")
}

/// `config list`'s human view. The command's serialized data is the key-to-value
/// object the JSON mode promises, which leaves no room for the origins, so the
/// rendered lines ride in as template context instead.
fn list_body(resolved: &Resolved, show_origin: bool) -> String {
    let mut body = String::new();
    for (key, entry) in resolved.entries() {
        if !body.is_empty() {
            body.push('\n');
        }
        body.push_str(&format!(
            "[config-key]{}[/config-key] = [config-value]{}[/config-value]",
            key,
            literal(&entry.value.render())
        ));
        if show_origin {
            body.push_str(&format!(
                " (from [config-origin]{}[/config-origin])",
