/// The framework's own `--output` is one of the layers that names a config
/// key, so it is read off the raw line rather than out of the parse: the
/// value the user typed is the flag layer, and the value this program appends
/// is only plumbing.
fn typed_output(argv: &[String]) -> Option<String> {
    let mut found = None;
    for (index, arg) in argv.iter().enumerate() {
        if arg == "--output" {
            if let Some(value) = argv.get(index + 1) {
                found = Some(value.clone());
            }
        } else if let Some(value) = arg.strip_prefix("--output=") {
            found = Some(value.to_string());
        }
    }
    found
}

struct Line {
    flags: Flags,
    show_origin: bool,
    /// Whether the resolved output mode should be appended to the arguments.
    steer_output: bool,
}

fn read_line(matches: &ArgMatches, argv: &[String]) -> Line {
    let overrides = matches
        .get_many::<String>("config_override")
        .map(|values| values.cloned().collect())
        .unwrap_or_default();

    let mut jobs = None;
    let mut features = None;
    let mut show_origin = false;
    match matches.subcommand() {
        Some(("build", sub)) => {
            jobs = sub.get_one::<String>("jobs").cloned();
            features = sub.get_one::<String>("features").cloned();
        }
        Some(("config", sub)) => {
            if let Some((_, inner)) = sub.subcommand() {
                show_origin = inner.get_flag("show_origin");
            }
        }
        _ => {}
    }

    let typed = typed_output(argv);
