    // is what steers the framework's own rendering.
    let probe = build_app(AppData { outcome: Ok(Resolved::default()) }, "", "")?;
    let parsed = probe.get_matches_from(Cli::command(), argv.clone(), &InputSources::from_process());

    let line = match &parsed {
        HelpResult::Matches(matches) => Some(read_line(matches, &argv)),
        // Help, a version display, or a usage error: nothing to resolve, and
        // the framework owns the answer.
        _ => None,
    };

    let mut args = argv.clone();
    let (outcome, show_origin, body) = match &line {
        Some(line) => {
            let outcome = config::resolve(&line.flags);
            if let (Ok(resolved), true) = (&outcome, line.steer_output) {
                args.push(format!("--output={}", resolved.output_mode()));
            }
            let body = match &outcome {
                Ok(resolved) => list_body(resolved, line.show_origin),
                Err(_) => String::new(),
            };
            (outcome, line.show_origin, body)
        }
        None => (Ok(Resolved::default()), false, String::new()),
    };

    let app = build_app(
        AppData { outcome },
        if show_origin { "1" } else { "" },
        leak(body),
    )?;
    app.run(Cli::command(), args);
    Ok(())
}

