//! `cargolike` — a tiny build planner in the cargo mold.
//!
//! Every number the tool reports comes out of a layered configuration, so the
//! whole of `main` is: parse the line, resolve the layers, hand the result to
//! the framework as app state, and let the handlers project it into a view.

mod config;
mod handlers;
mod state;
mod views;
mod workspace;

use clap::{ArgMatches, CommandFactory, Parser, Subcommand};
use standout::cli::{App, Dispatch, HelpResult};
use standout::{embed_styles, embed_templates, InputSources};

use config::{Flags, Resolved};
use state::AppData;

#[derive(Parser)]
#[command(name = "cargolike", about = "Report what a workspace contains and what building it would do")]
struct Cli {
    /// Set any known config key for this invocation, as `key=value`.
    #[arg(long = "config", value_name = "KEY=VALUE", global = true)]
    config_override: Vec<String>,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers)]
enum Commands {
    /// List the packages in the workspace and what they depend on.
    #[dispatch(pure)]
    Metadata {
        /// Narrow the command to one package.
        #[arg(short = 'p', long)]
        package: Option<String>,
    },

    /// Print the dependency tree rooted at a package.
    #[dispatch(pure)]
    Tree {
        /// The root of the tree; `cli` by default.
        #[arg(short = 'p', long)]
        package: Option<String>,
    },

    /// Report the build plan without building anything.
    #[dispatch(pure)]
    Build {
        /// Narrow the command to one package.
        #[arg(short = 'p', long)]
        package: Option<String>,
        /// Set `build.jobs` for this invocation.
        #[arg(long, value_name = "N")]
        jobs: Option<String>,
        /// Append comma-separated items to the effective feature list.
        #[arg(long, value_name = "LIST")]
        features: Option<String>,
    },

    /// Inspect the effective configuration.
    #[dispatch(nested)]
    #[command(subcommand)]
    Config(ConfigCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::config)]
enum ConfigCommands {
    /// Print the effective value of one config key.
    #[dispatch(pure)]
    Get {
        /// The key to read.
        key: String,
        /// Name the layer the value came from.
        #[arg(long)]
        show_origin: bool,
    },

    /// Print every key with an effective value.
    #[dispatch(pure)]
    List {
        /// Name the layer each value came from.
        #[arg(long)]
        show_origin: bool,
    },
}

// ---------------------------------------------------------------------------
// Presentation helpers
// ---------------------------------------------------------------------------

/// Pass 2 of the render pipeline reads `[...]` as a style tag, so a literal
/// bracket in a value has to be escaped on its way into the rendered text.
fn literal(text: &str) -> String {
    text.replace('[', "\\[").replace(']', "\\]")
}

/// `config list`'s human view. The command's serialized data is the key-to-value
/// object the JSON mode promises, which leaves no room for the origins, so the
/// rendered lines ride in as template context instead.
fn list_body(resolved: &Resolved, show_origin: bool) -> String {
    let mut body = String::new();
    for (key, entry) in resolved.entries() {
        if !body.is_empty() {
            body.push('\n');
        }
        body.push_str(&format!(
            "[config-key]{}[/config-key] = [config-value]{}[/config-value]",
            key,
            literal(&entry.value.render())
        ));
        if show_origin {
            body.push_str(&format!(
                " (from [config-origin]{}[/config-origin])",
                entry.origin.as_str()
            ));
        }
    }
    body
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------

fn build_app(
    data: AppData,
    show_origin: bool,
    list_body: String,
) -> Result<App, Box<dyn std::error::Error>> {
    Ok(App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .app_state(data)
        .context("show_origin", show_origin.into())
        .context("config_list_body", list_body.into())
        .commands(Commands::dispatch_config())?
        .build()?)
}

/// The framework's own `--output` is one of the layers that names a config
/// key, so it is read off the raw line rather than out of the parse: the
/// value the user typed is the flag layer, and the value this program appends
/// is only plumbing.
fn typed_output(argv: &[String]) -> Option<String> {
    let mut found = None;
    for (index, arg) in argv.iter().enumerate() {
        if arg == "--output" {
            if let Some(value) = argv.get(index + 1) {
                found = Some(value.clone());
            }
        } else if let Some(value) = arg.strip_prefix("--output=") {
            found = Some(value.to_string());
        }
    }
    found
}

/// Drop every `--output` the line carries, so the resolved mode can be
/// appended in its place. The framework's flag takes a single value, so
/// steering it means replacing what the user typed rather than following it.
fn without_output(argv: &[String]) -> Vec<String> {
    let mut kept = Vec::with_capacity(argv.len());
    let mut skip_value = false;
    for arg in argv {
        if skip_value {
            skip_value = false;
            continue;
        }
        if arg == "--output" {
            skip_value = true;
            continue;
        }
        if arg.starts_with("--output=") {
            continue;
        }
        kept.push(arg.clone());
    }
    kept
}

struct Line {
    flags: Flags,
    show_origin: bool,
    /// Whether the resolved output mode should be appended to the arguments.
    steer_output: bool,
}

fn read_line(matches: &ArgMatches, argv: &[String]) -> Line {
    let overrides = matches
        .get_many::<String>("config_override")
        .map(|values| values.cloned().collect())
        .unwrap_or_default();

    let mut jobs = None;
    let mut features = None;
    let mut show_origin = false;
    match matches.subcommand() {
        Some(("build", sub)) => {
            jobs = sub.get_one::<String>("jobs").cloned();
            features = sub.get_one::<String>("features").cloned();
        }
        Some(("config", sub)) => {
            if let Some((_, inner)) = sub.subcommand() {
                show_origin = inner.get_flag("show_origin");
            }
        }
        _ => {}
    }

    let typed = typed_output(argv);
    // Only a value `term.output` can hold is a flag-layer contribution; any
    // other output mode the framework accepts is left entirely to it.
    let output = typed
        .as_deref()
        .filter(|value| ["auto", "text", "term", "json"].contains(value))
        .map(str::to_string);
    let steer_output = typed.is_none() || output.is_some();

    Line { flags: Flags { overrides, jobs, features, output }, show_origin, steer_output }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let argv: Vec<String> = std::env::args().collect();

    // A first parse only to read the layers the command line carries; the
    // resolved configuration has to exist before the app is built, because it
    // is what steers the framework's own rendering.
    let probe = build_app(AppData { outcome: Ok(Resolved::default()) }, false, String::new())?;
    let parsed = probe.get_matches_from(Cli::command(), argv.clone(), &InputSources::from_process());

    let line = match &parsed {
        HelpResult::Matches(matches) => Some(read_line(matches, &argv)),
        // Help, a version display, or a usage error: nothing to resolve, and
        // the framework owns the answer.
        _ => None,
    };

    let mut args = argv.clone();
    let (outcome, show_origin, body) = match &line {
        Some(line) => {
            let outcome = config::resolve(&line.flags);
            if let (Ok(resolved), true) = (&outcome, line.steer_output) {
                args = without_output(&argv);
                args.push(format!("--output={}", resolved.output_mode()));
            }
            let body = match &outcome {
                Ok(resolved) => list_body(resolved, line.show_origin),
                Err(_) => String::new(),
            };
            (outcome, line.show_origin, body)
        }
        None => (Ok(Resolved::default()), false, String::new()),
    };

    let app = build_app(AppData { outcome }, show_origin, body)?;
    app.run(Cli::command(), args);
    Ok(())
}

