    #[dispatch(nested)]
    #[command(subcommand)]
    Config(ConfigCommands),
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = crate::handlers::config)]
enum ConfigCommands {
    /// Print the effective value of one config key.
    #[dispatch(pure)]
    Get {
        /// The key to read.
        key: String,
        /// Name the layer the value came from.
        #[arg(long)]
        show_origin: bool,
    },

    /// Print every key with an effective value.
    #[dispatch(pure)]
    List {
        /// Name the layer each value came from.
        #[arg(long)]
        show_origin: bool,
    },
}

// ---------------------------------------------------------------------------
// Presentation helpers
// ---------------------------------------------------------------------------

/// Pass 2 of the render pipeline reads `[...]` as a style tag, so a literal
/// bracket in a value has to be escaped on its way into the rendered text.
fn literal(text: &str) -> String {
    text.replace('[', "\\[").replace(']', "\\]")
}

/// One `config` line: the value as `config list` spells it, and the provenance
/// when it was asked for.
fn config_line(entry: &config::Entry, show_origin: bool) -> String {
    let mut line = format!("[config-value]{}[/config-value]", literal(&entry.value.render()));
    if show_origin {
        line.push_str(&format!(" (from [config-origin]{}[/config-origin])", entry.origin.as_str()));
    }
    line
}

/// The human view of the `config` commands. Their serialized data is the shape
/// the JSON mode promises — a key-to-value object for `list`, a typed value
/// plus its origin for `get` — which leaves no room for `--show-origin`'s
/// rendering, so the rendered lines ride in as template context instead.
fn config_views(resolved: &Resolved, line: &Line) -> (String, String) {
    let mut body = String::new();
    for (key, entry) in resolved.entries() {
        if !body.is_empty() {
            body.push('\n');
        }
        body.push_str(&format!("[config-key]{}[/config-key] = ", key));
        body.push_str(&config_line(entry, line.show_origin));
    }

    let get = line
        .key
        .as_deref()
        .and_then(|key| resolved.get(key))
        .map(|entry| config_line(entry, line.show_origin))
        .unwrap_or_default();

    (body, get)
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------

fn build_app(
    data: AppData,
    list_body: String,
    get_line: String,
) -> Result<App, Box<dyn std::error::Error>> {
    Ok(App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .app_state(data)
        .context("config_list_body", list_body.into())
        .context("config_get_line", get_line.into())
        .commands(Commands::dispatch_config())?
        .build()?)
}

/// The framework's own `--output` is one of the layers that names a config
/// key, so it is read off the raw line rather than out of the parse: the
/// value the user typed is the flag layer, and the value this program appends
/// is only plumbing.
fn typed_output(argv: &[String]) -> Option<String> {
    let mut found = None;
    for (index, arg) in argv.iter().enumerate() {
        if arg == "--output" {
            if let Some(value) = argv.get(index + 1) {
                found = Some(value.clone());
            }
        } else if let Some(value) = arg.strip_prefix("--output=") {
            found = Some(value.to_string());
        }
    }
    found
}

/// Drop every `--output` the line carries, so the resolved mode can be
/// appended in its place. The framework's flag takes a single value, so
/// steering it means replacing what the user typed rather than following it.
fn without_output(argv: &[String]) -> Vec<String> {
    let mut kept = Vec::with_capacity(argv.len());
    let mut skip_value = false;
    for arg in argv {
        if skip_value {
            skip_value = false;
            continue;
        }
        if arg == "--output" {
            skip_value = true;
            continue;
        }
        if arg.starts_with("--output=") {
            continue;
        }
        kept.push(arg.clone());
    }
    kept
}

/// What the command line says, beyond what the handlers read for themselves.
struct Line {
    flags: Flags,
    show_origin: bool,
    /// The key `config get` was asked for, when that is the command.
    key: Option<String>,
    /// Whether the resolved output mode should replace what the line carries.
    steer_output: bool,
}

fn read_line(matches: &ArgMatches, argv: &[String]) -> Line {
    let overrides = matches
        .get_many::<String>("config_override")
        .map(|values| values.cloned().collect())
        .unwrap_or_default();

    let mut jobs = None;
    let mut features = None;
    let mut show_origin = false;
    let mut key = None;
    match matches.subcommand() {
        Some(("build", sub)) => {
            jobs = sub.get_one::<String>("jobs").cloned();
            features = sub.get_one::<String>("features").cloned();
        }
        Some(("config", sub)) => {
            if let Some((_, inner)) = sub.subcommand() {
                show_origin = inner.get_flag("show_origin");
                key = inner.get_one::<String>("key").cloned();
            }
        }
        _ => {}
    }

    let typed = typed_output(argv);
    // Only a value `term.output` can hold is a flag-layer contribution; any
    // other output mode the framework accepts is left entirely to it.
    let output = typed
        .as_deref()
        .filter(|value| ["auto", "text", "term", "json"].contains(value))
        .map(str::to_string);
    let steer_output = typed.is_none() || output.is_some();

    Line { flags: Flags { overrides, jobs, features, output }, show_origin, key, steer_output }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let argv: Vec<String> = std::env::args().collect();

    // A first parse only to read the layers the command line carries; the
    // resolved configuration has to exist before the app is built, because it
    // is what steers the framework's own rendering.
    let probe =
        build_app(AppData { outcome: Ok(Resolved::default()) }, String::new(), String::new())?;
    let parsed = probe.get_matches_from(Cli::command(), argv.clone(), &InputSources::from_process());

    let line = match &parsed {
        HelpResult::Matches(matches) => Some(read_line(matches, &argv)),
        // Help, a version display, or a usage error: nothing to resolve, and
        // the framework owns the answer.
        _ => None,
    };

    let mut args = argv.clone();
    let (outcome, body, get) = match &line {
        Some(line) => {
            let outcome = config::resolve(&line.flags);
            let mut views = (String::new(), String::new());
            if let Ok(resolved) = &outcome {
                if line.steer_output {
                    args = without_output(&argv);
                    args.push(format!("--output={}", resolved.output_mode()));
                }
                views = config_views(resolved, line);
            }
            (outcome, views.0, views.1)
        }
        None => (Ok(Resolved::default()), String::new(), String::new()),
    };

    let app = build_app(AppData { outcome }, body, get)?;
    app.run(Cli::command(), args);
    Ok(())
}

